import raw from './ideas.json'

// ideas.json is generated by scripts/build-ideas.mjs from content/ideas/*.md. Edit the markdown, not the JSON.
export type Segment = { type: 'note'; html: string } | { type: 'prompt'; label: string; text: string }
export type Status = 'first-try' | 'fixed' | 'edit' | 'untested'

export type Idea = {
  id: string
  slug: string
  batch: number
  date: string
  title: string
  category: string
  grades: string
  tool: string
  time: string
  status: Status
  verdict: string
  verdictDetail: string
  summary: string
  prompt: string
  segments: Segment[]
  testHtml: string
  sourcesHtml: string
}

export const ideas = raw as Idea[]
export const getIdea = (slug: string) => ideas.find((i) => i.slug === slug)

export const STAMP: Record<Status, string> = {
  'first-try': 'Worked first try',
  fixed: 'Fixed + retested',
  edit: 'Needs a quick edit',
  untested: 'Not tested yet',
}

export const CATEGORIES: Record<string, { icon: string; color: string; tint: string; blurb: string }> = {
  Planning: { icon: '🗓️', color: '#2544d8', tint: '#e6eafd', blurb: 'Sub plans, hooks, blind spots' },
  Differentiation: { icon: '🧩', color: '#6d28d9', tint: '#efe7fe', blurb: 'Same goal, more ways in' },
  Assessment: { icon: '✅', color: '#b45309', tint: '#fdf0d5', blurb: 'Exit tickets, rubrics, sorting' },
  Feedback: { icon: '✍️', color: '#be185d', tint: '#fce7f1', blurb: 'Writing feedback, report cards' },
  'Parent communication': { icon: '🏡', color: '#047857', tint: '#d9f5e8', blurb: 'Newsletters, hard emails' },
  'Classroom routines': { icon: '🔔', color: '#c2410c', tint: '#ffeadb', blurb: 'Teach a routine with a story' },
  'Students and AI': { icon: '🤖', color: '#0369a1', tint: '#dff1fc', blurb: 'Guardrails, AI literacy' },
  Tools: { icon: '🧰', color: '#0f766e', tint: '#d5f5f0', blurb: 'Free plans and new features' },
}

export const categoryOf = (name: string) => CATEGORIES[name] ?? { icon: '✨', color: '#2544d8', tint: '#e6eafd', blurb: '' }

export const stats = {
  total: ideas.length,
  tested: ideas.filter((i) => i.status !== 'untested').length,
  firstTry: ideas.filter((i) => i.status === 'first-try').length,
  fixed: ideas.filter((i) => i.status === 'fixed').length,
}
